import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/material.dart';
import '../../../app/atlas_academy_app.dart';

class AdminMcqCurriculumScreen extends StatefulWidget {
 const AdminMcqCurriculumScreen({super.key});
 @override State<AdminMcqCurriculumScreen> createState()=>_AdminMcqCurriculumScreenState();
}
class _AdminMcqCurriculumScreenState extends State<AdminMcqCurriculumScreen> {
 final db=FirebaseFirestore.instance;
 final name=TextEditingController(), code=TextEditingController(), description=TextEditingController();
 String track='licensing', parentId='', parentName='', subjectId='', subjectName='';
 @override void dispose(){name.dispose();code.dispose();description.dispose();super.dispose();}
 Future<void> _create(String collection,Map<String,dynamic> extra) async {
  name.clear();code.clear();description.clear();
  final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text('Create ${collection=='mcq_exam_sets'?'exam set':collection=='licensing_pathways'?'pathway':'subject'}'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Name')),TextField(controller:code,decoration:const InputDecoration(labelText:'Code (optional)')),if(collection=='licensing_pathways')TextField(controller:description,decoration:const InputDecoration(labelText:'Description'),maxLines:2)])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Create'))]));
  if(ok!=true||name.text.trim().isEmpty)return;
  final data=<String,dynamic>{...extra,'name':name.text.trim(),'code':code.text.trim(),'isActive':true,'createdAt':FieldValue.serverTimestamp(),'updatedAt':FieldValue.serverTimestamp()};
  if(collection=='licensing_pathways')data['description']=description.text.trim();
  if(collection=='mcq_exam_sets'){data.addAll({'isPublished':false,'order':0});}
  await db.collection(collection).add(data);
 }
 Future<void> _toggle(String collection,QueryDocumentSnapshot<Map<String,dynamic>> doc,String field) async {await doc.reference.update({field:!(doc.data()[field]==true),'updatedAt':FieldValue.serverTimestamp()});}
 Widget _card(String title,String subtitle,IconData icon,Widget child){return Container(margin:const EdgeInsets.only(bottom:16),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18),border:Border.all(color:AtlasColors.border)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Icon(icon,color:AtlasColors.royalBlue),const SizedBox(width:10),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontWeight:FontWeight.w900,color:AtlasColors.navy)),Text(subtitle,style:const TextStyle(fontSize:11,color:AtlasColors.secondaryText))]))]),const SizedBox(height:12),child]));}
 Widget _list(String collection,{required String empty,required String activeField})=>StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:db.collection(collection).snapshots(),builder:(c,s){if(s.hasError)return const Text('Unable to load records.');if(!s.hasData)return const LinearProgressIndicator();if(s.data!.docs.isEmpty)return Text(empty);return Column(children:s.data!.docs.map((d){final data=d.data();return ListTile(contentPadding:EdgeInsets.zero,title:Text((data['name']??'Unnamed').toString(),style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(data[activeField]==true?'Active':'Inactive'),trailing:IconButton(icon:Icon(data[activeField]==true?Icons.toggle_on:Icons.toggle_off,color:AtlasColors.royalBlue,size:30),onPressed:()=>_toggle(collection,d,activeField)));}).toList());});
 @override Widget build(BuildContext context)=>Scaffold(backgroundColor:AtlasColors.ivory,appBar:AppBar(title:const Text('MCQ Curriculum Management'),backgroundColor:AtlasColors.navy,foregroundColor:Colors.white),body:ListView(padding:const EdgeInsets.all(16),children:[
 _card('Licensing pathways','Create and activate licensing routes',Icons.route_rounded,Column(children:[_list('licensing_pathways',empty:'No pathways created yet.',activeField:'isActive'),Align(alignment:Alignment.centerRight,child:FilledButton.icon(onPressed:()=>_create('licensing_pathways',{}),icon:const Icon(Icons.add),label:const Text('Add pathway')))])),
 _card('Pathway subjects','Subjects belonging to licensing pathways',Icons.menu_book_rounded,Column(children:[StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:db.collection('licensing_pathways').where('isActive',isEqualTo:true).snapshots(),builder:(c,s){if(!s.hasData)return const LinearProgressIndicator();return DropdownButtonFormField<String>(value:s.data!.docs.any((d)=>d.id==parentId)?parentId:null,decoration:const InputDecoration(labelText:'Select pathway',border:OutlineInputBorder()),items:s.data!.docs.map((d)=>DropdownMenuItem(value:d.id,child:Text((d.data()['name']??'').toString()))).toList(),onChanged:(v){setState((){parentId=v??'';parentName=s.data!.docs.firstWhere((d)=>d.id==v).data()['name'].toString();});});}),if(parentId.isNotEmpty)...[_list('licensing_pathway_subjects',empty:'No subjects for this pathway.',activeField:'isActive'),Align(alignment:Alignment.centerRight,child:FilledButton.icon(onPressed:()=>_create('licensing_pathway_subjects',{'pathwayId':parentId,'pathwayName':parentName}),icon:const Icon(Icons.add),label:const Text('Add subject')))] ])),
 _card('MBBS and licensing exam sets','Create multiple exam sets under each subject',Icons.quiz_rounded,Column(children:[DropdownButtonFormField<String>(value:track,decoration:const InputDecoration(labelText:'Track',border:OutlineInputBorder()),items:const [DropdownMenuItem(value:'mbbs',child:Text('MBBS')),DropdownMenuItem(value:'licensing',child:Text('Licensing'))],onChanged:(v)=>setState(()=>track=v??'mbbs')),const SizedBox(height:10),StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:db.collection(track=='mbbs'?'academic_years':'licensing_pathways').snapshots(),builder:(c,s){if(!s.hasData)return const LinearProgressIndicator();return DropdownButtonFormField<String>(value:s.data!.docs.any((d)=>d.id==parentId)?parentId:null,decoration:InputDecoration(labelText:track=='mbbs'?'Academic year':'Pathway',border:const OutlineInputBorder()),items:s.data!.docs.map((d)=>DropdownMenuItem(value:d.id,child:Text((d.data()['name']??d.data()['title']??d.id).toString()))).toList(),onChanged:(v){final d=s.data!.docs.firstWhere((x)=>x.id==v);setState((){parentId=v??'';parentName=(d.data()['name']??d.data()['title']??'').toString();subjectId='';});});}),if(parentId.isNotEmpty)StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:db.collection(track=='mbbs'?'academic_subjects':'licensing_pathway_subjects').where(track=='mbbs'?'yearId':'pathwayId',isEqualTo:parentId).snapshots(),builder:(c,s){if(!s.hasData)return const LinearProgressIndicator();return DropdownButtonFormField<String>(value:s.data!.docs.any((d)=>d.id==subjectId)?subjectId:null,decoration:const InputDecoration(labelText:'Subject',border:OutlineInputBorder()),items:s.data!.docs.map((d)=>DropdownMenuItem(value:d.id,child:Text((d.data()['name']??d.id).toString()))).toList(),onChanged:(v){final d=s.data!.docs.firstWhere((x)=>x.id==v);setState((){subjectId=v??'';subjectName=(d.data()['name']??'').toString();});});}),if(subjectId.isNotEmpty)Align(alignment:Alignment.centerRight,child:FilledButton.icon(onPressed:()=>_create('mcq_exam_sets',{'trackType':track,'yearId':track=='mbbs'?parentId:'','yearName':track=='mbbs'?parentName:'','pathwayId':track=='licensing'?parentId:'','pathwayName':track=='licensing'?parentName:'','subjectId':subjectId,'subjectName':subjectName}),icon:const Icon(Icons.add),label:const Text('Add exam set'))),const SizedBox(height:8),_list('mcq_exam_sets',empty:'No exam sets created yet.',activeField:'isPublished')]))
 ]));
}
